"""Human workflow and matching API instructions share one role-scoped guide."""
import json
from .search_contract import SEARCH_EXAMPLE, SEARCH_RESPONSE_EXAMPLE


def search_blocks(*, library, writer, student):
    blocks=[]
    if library:
        blocks.append(dict(title='Поиск в банке задач',steps=[
            'Откройте «Банк задач». Вставьте условие, решение, фрагмент текста или ID P-123 в поле поиска.',
            'Отметьте «В условиях», «В решениях» или оба варианта. Выберите несколько тегов или веток дерева тем при необходимости.',
            'Дождитесь результатов, откройте подходящую задачу и сравните условие, числа, знаки и формулы.'],api_steps=[
            'Выполните POST /api/v1/problem-search: q — введённый текст, scope=library, field=statement/solution/metadata/all.',
            'Для нескольких фильтров передайте массивы tag с числовыми ID и topic с UUID. Ветки тем включают потомков.',
            'Прочитайте results[].problem.id и откройте задачу через GET /api/v1/materials/problem/{id}. Не используйте публичный P-ID вместо UUID в пути.']))
    if student:
        blocks.append(dict(title='Поиск в «Моих задачах»',steps=[
            'Откройте «Мои задачи» и выберите вкладку «Задачи». Вставьте текст в поиск; теги сужают результаты.',
            'Поиск учитывает только задачи, которые вам назначались. Для роли student показ решения должен быть разрешён хотя бы в одном вашем действующем кружке; дополнительные роли могут давать более широкий доступ.',
            'Откройте найденную задачу. Снятие разрешения на решение действует сразу и не требует переиндексации.'],api_steps=[
            'Передайте POST /api/v1/problem-search с scope=my и q. Можно задать field=statement/solution/metadata/all и массив tag.',
            'Для аккаунта без teacher/analyst/admin даже scope=library автоматически ограничивается my. При нескольких ролях доступ объединяется.',
            'Откройте результат через GET /api/v1/my-problems/{id}. Закрытые решения отсутствуют и в материале, и в поисковых фрагментах.']))
    if writer:
        blocks.append(dict(title='Проверка перед созданием задачи',steps=[
            'Начните добавлять задачу и заполните условие либо решение. Раздел проверки совпадений появляется до сохранения.',
            'В проверке переключите «По условию» или «По решению». Сервис берёт текст соответствующего поля; если обычный текст пуст, используется его TeX.',
            'Сравните кандидатов. «Использовать задачу» открывает существующую запись без создания дубля; если это другой вариант, продолжите создание своей задачи.'],api_steps=[
            'Перед созданием материала выполните POST /api/v1/problem-search с q из statement/statement_tex и field=statement либо из solution/solution_tex и field=solution.',
            'Прочитайте первые результаты и сравните числа, условия и формулы. Совпадение по смыслу не является проверкой математической эквивалентности.',
            'Если подходит существующая задача, сохраните её problem.id для листка. Иначе отдельно создайте материал через POST /api/v1/materials/problem. Поиск сам ничего не сохраняет.']))
    blocks.append(dict(title='Подбор задачи в листок',steps=[
        ('При создании или редактировании собственного листка вставьте текст либо ID в поиск задач. Выбранные ранее задачи сохраняются.' if writer else 'При редактировании своей копии листка вставьте текст либо ID в поиск задач. Выбранные ранее задачи сохраняются.'),
        'Нажмите «Использовать задачу» у нужного кандидата. Кнопка «Убрать из листка» отменяет выбор; порядок задач можно изменить отдельно.'],api_steps=[
        'Найдите кандидатов через POST /api/v1/problem-search и соберите уникальные results[].problem.id в нужном порядке.',
        ('Передайте UUID в массиве problems при создании листка через POST /api/v1/materials/worksheet или сохранении своей версии через PATCH /api/v1/worksheet-documents/{document_id}. Поиск сам не меняет состав листка.' if writer else 'Редактируйте собственную копию: PATCH /api/v1/worksheet-documents/{document_id} с version и problems. Для получения личной копии используйте POST /api/v1/worksheets/{id}/copy. Изменения требуют права записи; поиск сам ничего не меняет.')]))
    blocks += [
        dict(title='Как читать совпадения',table={'columns':['Метка / поле','Что означает'], 'rows':[
            ['Совпадение ID · identifier','Найдена задача по идентификатору; fields и excerpt пусты. Семантический индекс не проверяется: semantic=false, pending=0, notice пустой.'],
            ['Текст совпадает · exact','Нормализованный текст совпал: пробелы и переносы несущественны; числа, регистр переменных и операторы сохраняются.'],
            ['Похожий текст · text','Совпадение фрагмента, близкий текст или прежний поиск по названию/источнику. Это не доказательство дубля.'],
            ['Близко по смыслу · semantic','Локальная модель нашла близкий по смыслу материал. Обязательно сравните математическое содержание.'],
            ['fields / excerpt','Разрешённые поля совпадения и фрагмент одного из них, до 500 символов. Закрытые решения не используются.'],
            ['semantic','true — в этом запросе участвовала модель; false бывает при mode=text, поиске ID, недоступной модели или ещё неготовых векторах.'],
            ['pending / notice','Количество доступных поисковых документов, ожидающих индексации, и пояснение ограничения выдачи. Это не число задач: условие, решение и название/описание считаются отдельно. Для поиска ID pending=0 не описывает готовность индекса.']]}),
        dict(title='Если результат неполный',bullets=[
            'Новые задачи сначала доступны по тексту, затем фоновый индексатор добавляет векторы. Исходные задачи и решения при этом не меняются.',
            'При остановленной модели запрос остаётся успешным: HTTP 200, текстовые результаты и notice. Не запускайте бесконечные повторы, ожидая semantic=true.',
            'Пустой results не доказывает отсутствие дубля: проверьте формулировку, теги, темы и свою область доступа.',
            'Показаны первые limit результатов по релевантности, без общего count и страниц. Совпадения автоматически не объединяются.']),
        dict(title='Параметры API поиска',table={'columns':['Поле','Значения и назначение'], 'rows':[
            ['q','Обязательно: непустой текст до 12 000 символов или P-ID/UUID.'],
            ['field','all (по умолчанию), statement, solution или metadata (название и описание); непустой массив fields задаёт набор полей.'],
            ['scope','library (по умолчанию) либо my; my требует роли student. Права нескольких ролей объединяются.'],
            ['mode','hybrid (по умолчанию) либо text.'],
            ['limit','Целое 1–50, по умолчанию 20.'],
            ['tag / topic','В JSON массивы числовых ID тегов задач / UUID тем. В GET повторяйте параметры. Внутри вида фильтра ИЛИ, между видами И.']]}),
        dict(title='Пример запроса: поиск по условию',code={'language':'json','content':json.dumps(
            {**SEARCH_EXAMPLE,**({'scope':'my'} if not library else {})},ensure_ascii=False,indent=2)}),
        dict(title='Пример запроса: поиск по решению',code={'language':'json','content':json.dumps(
            {'q':'Представим оба числа в виде 2a и 2b. Их сумма равна 2(a+b).','field':'solution',
             'scope':'library' if library else 'my','mode':'hybrid','limit':5},ensure_ascii=False,indent=2)}),
        dict(title='Пример ответа поиска',code={'language':'json','content':json.dumps(SEARCH_RESPONSE_EXAMPLE,ensure_ascii=False,indent=2)}),
        dict(title='Как отправлять запросы API',paragraphs=[
            'Основной вариант — POST /api/v1/problem-search с Content-Type: application/json и JSON-телом из примера. Это операция чтения, разрешённая токену read_only.',
            'Для коротких запросов есть GET /api/v1/problem-search?q=P-12. Длинные условия и решения передавайте через POST, чтобы не упираться в ограничения длины URL.',
            'Боты используют Authorization: Bearer <token>. В браузерной сессии POST требует обычный CSRF-заголовок. Справочник API только показывает контракт и не отправляет запросы.',
            'Для примера curl сохраните JSON запроса в search.json, задайте адрес сервиса в PLUSFOLIO_URL и личный токен в PLUSFOLIO_TOKEN. Значение токена не помещайте в исходники или логи.']),
        dict(title='Пример вызова API из терминала',code={'language':'bash','content':'''curl "$PLUSFOLIO_URL/api/v1/problem-search" \\
  -X POST \\
  -H "Authorization: Bearer $PLUSFOLIO_TOKEN" \\
  -H 'Content-Type: application/json' \\
  --data-binary @search.json'''}),
        dict(title='Ошибки и ограничения API',table={'columns':['Статус','Действие'], 'rows':[
            ['400','Проверьте q, типы, field/scope/mode, limit, ID тегов и тем. Исправьте запрос перед повтором.'],
            ['401 / 403','Проверьте токен, роли, CSRF для сессии. Для scope=my нужна роль student. Поиск не расширяет доступ.'],
            ['429','Подождите Retry-After. Лимит — 60 поисков в минуту на аккаунт в текущем Django cache; для нескольких процессов нужен общий cache backend.'],
            ['200 с notice','Это частичный или текстовый результат, а не ошибка HTTP. Прочитайте notice, semantic и pending.']]}),
    ]
    return blocks
